WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x0d0d0b,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene_f06.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(203),
      minute_startY: px(119),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_x4sf,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon Main (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(175),
      y: px(132),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(11),
      hour_startY: px(119),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_x308,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(206),
      minute_startY: px(160),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_q4o2,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(178),
      y: px(171),
      src: A('symbol_u003a_2.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(38),
      hour_startY: px(160),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_q4na,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(121),
      y: px(84),
      week_en: img_Weekday_ekv1,
      week_sc: img_Weekday_ekv1,
      week_tc: img_Weekday_ekv1,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(208),
      day_startY: px(89),
      day_zero: 0,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_ffey,
      day_sc_array: img_Day_ffey,
      day_tc_array: img_Day_ffey,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(33),
      y: px(299),
      type: ui.data_type.STEP,
      font_array: img_Steps_o2bf,
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(205),
      y: px(299),
      type: ui.data_type.HEART,
      font_array: img_Heart_rate_310o,
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Tag (IMG)
    const variants_0 = [A('sp/tag_001.png'), A('sp/tag_000.png'), A('sp/tag_002.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(232),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tag = variant_0
    F.tag = variants_0

    // Ticker 1 (IMG)
    const variants_1 = [A('sp/tk0_003.png'), A('sp/tk0_004.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(394),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tk0 = variant_1
    F.tk0 = variants_1

    // Ticker 2 (IMG)
    const variants_2 = [A('sp/tk1_006.png'), A('sp/tk1_005.png')]
    const variant_2 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(394),
      src: variants_2[variantIdx % variants_2.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tk1 = variant_2
    F.tk1 = variants_2

    // Ticker 3 (IMG)
    const variants_3 = [A('sp/tk2_008.png'), A('sp/tk2_007.png')]
    const variant_3 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(394),
      src: variants_3[variantIdx % variants_3.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tk2 = variant_3
    F.tk2 = variants_3

    // Ticker 4 (IMG)
    const variants_4 = [A('sp/tk3_010.png'), A('sp/tk3_009.png')]
    const variant_4 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(394),
      src: variants_4[variantIdx % variants_4.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tk3 = variant_4
    F.tk3 = variants_4

    // Ticker 5 (IMG)
    const variants_5 = [A('sp/tk4_012.png'), A('sp/tk4_011.png')]
    const variant_5 = ui.createWidget(ui.widget.IMG, {
      x: px(36),
      y: px(394),
      src: variants_5[variantIdx % variants_5.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.tk4 = variant_5
    F.tk4 = variants_5

    // Cover L (IMG)
    const variants_6 = [A('sp/CoverL_013.png'), A('sp/CoverL_014.png')]
    const variant_6 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(390),
      src: variants_6[variantIdx % variants_6.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.CoverL = variant_6
    F.CoverL = variants_6

    // Cover R (IMG)
    const variants_7 = [A('sp/CoverR_015.png'), A('sp/CoverR_016.png')]
    const variant_7 = ui.createWidget(ui.widget.IMG, {
      x: px(360),
      y: px(390),
      src: variants_7[variantIdx % variants_7.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.CoverR = variant_7
    F.CoverR = variants_7

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length, variants_2.length, variants_3.length, variants_4.length, variants_5.length, variants_6.length, variants_7.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
      variant_2.setProperty(ui.prop.SRC, variants_2[variantIdx % variants_2.length])
      variant_3.setProperty(ui.prop.SRC, variants_3[variantIdx % variants_3.length])
      variant_4.setProperty(ui.prop.SRC, variants_4[variantIdx % variants_4.length])
      variant_5.setProperty(ui.prop.SRC, variants_5[variantIdx % variants_5.length])
      variant_6.setProperty(ui.prop.SRC, variants_6[variantIdx % variants_6.length])
      variant_7.setProperty(ui.prop.SRC, variants_7[variantIdx % variants_7.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // Monitorul de pe mână: the tag blinks and a red ticker runs the headlines, forever
      const MS = 100, TX0 = 36, TL = 1453, CW = 290.6, K = 5, SPEED = 70;
      const V = {"tag":{"b":0,"a":1,"__blank":2},"tk0":{"s":0,"__blank":1},"tk1":{"__blank":0,"s":1},"tk2":{"__blank":0,"s":1},"tk3":{"__blank":0,"s":1},"tk4":{"__blank":0,"s":1},"CoverL":{"s":0,"__blank":1},"CoverR":{"s":0,"__blank":1}};
      const tick = () => {
        const now = Date.now();
        slot('tag')(36, 232, V.tag[Math.floor(now / 500) % 2 ? 'a' : 'b']);
        const off = (now / 1000 * SPEED) % TL;
        for (let i = 0; i < K; i++) { const p = (((i * CW - off) % TL) + TL) % TL; slot('tk' + i)(Math.round(TX0 + (p > TL - CW ? p - TL : p)), 394, V['tk' + i].s); }
      };
        // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();

    }
  },

  build() {
    this.initView()
  },
})
